import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, length, smoothstep, time, sin, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Shape, ExtrudeGeometry, Mesh, PlaneGeometry, PointLight, Color } = THREE;

  const COLORS = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const spec = config.intent?.visualSpec?.colors ?? {};
  const palette = { ...COLORS, ...spec };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Journal 3', role: 'headline', typography: { fontSize: 39 } },
    ];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const labelText = headlineItem?.text ?? 'Journal 3';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const root = new Group();
  root.name = 'hub-journal-card-0-label';

  // ---------- geometry helpers ----------
  function roundedRectShape(w, h, r) {
    const shape = new Shape();
    const x = -w / 2;
    const y = -h / 2;
    shape.moveTo(x, y + r);
    shape.lineTo(x, y + h - r);
    shape.quadraticCurveTo(x, y + h, x + r, y + h);
    shape.lineTo(x + w - r, y + h);
    shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
    shape.lineTo(x + w, y + r);
    shape.quadraticCurveTo(x + w, y, x + w - r, y);
    shape.lineTo(x + r, y);
    shape.quadraticCurveTo(x, y, x, y + r);
    return shape;
  }

  const CARD_W = 1.5;
  const CARD_H = 0.46;
  const CARD_R = 0.06;
  const CARD_DEPTH = 0.06;

  const cardShape = roundedRectShape(CARD_W, CARD_H, CARD_R);
  const cardGeo = new ExtrudeGeometry(cardShape, {
    depth: CARD_DEPTH,
    bevelEnabled: true,
    bevelThickness: 0.012,
    bevelSize: 0.012,
    bevelSegments: 3,
    curveSegments: 8,
  });
  cardGeo.translate(0, 0, -CARD_DEPTH / 2);

  // machined-metal card body — muted ink, low-key PBR
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(palette.ink),
    roughness: 0.55,
    metalness: 0.42,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.castShadow = false;
  cardMesh.receiveShadow = false;
  root.add(cardMesh);

  // ---------- accent focus/hover glow (edge halo) ----------
  const accentColor = new Color(palette.accent);
  const accentGeo = new PlaneGeometry(CARD_W * 1.18, CARD_H * 1.32);
  const accentMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    opacity: 0.0,
  });
  const accentAlpha = smoothstep(0.5, 0.02, length(uv().sub(vec2(0.5, 0.5))));
  const breathe = add(0.75, mul(0.25, sin(time.mul(1.4))));
  accentMat.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b).mul(breathe);
  accentMat.opacityNode = accentAlpha.mul(0.55);
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, 0, -CARD_DEPTH / 2 - 0.01);
  accentMesh.visible = true;
  root.add(accentMesh);

  // ---------- contact shadow (grounded object) ----------
  const shadowGeo = new PlaneGeometry(CARD_W * 1.5, CARD_H * 1.8);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  const shadowAlpha = smoothstep(0.5, 0.0, length(uv().sub(vec2(0.5, 0.5))));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowAlpha.mul(0.45);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -CARD_H * 0.62, -0.02);
  root.add(shadowMesh);

  // ---------- local rim light (accent-tinted, node-scoped) ----------
  const rimLight = new PointLight(new Color(palette.accent), 0.7, 3.0, 2.0);
  rimLight.position.set(-0.6, 0.3, 0.6);
  root.add(rimLight);

  // ---------- decorative accent icon from provided asset ----------
  let accentIconTex = null;
  let accentIconMesh = null;
  if (config.imageUrl) {
    const iconGeo = new PlaneGeometry(0.16, 0.16);
    const iconMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    accentIconMesh = new Mesh(iconGeo, iconMat);
    accentIconMesh.position.set(-CARD_W / 2 + 0.16, 0, CARD_DEPTH / 2 + 0.015);
    root.add(accentIconMesh);
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      accentIconTex = tex;
      iconMat.map = tex;
      iconMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------- label text (MSDF) ----------
  const text = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: palette.paper,
    align: 'center',
  });
  text.position.set(0.06, -0.005, CARD_DEPTH / 2 + 0.02);
  root.add(text);

  // ---------- motion: entrance (weighted settle) ----------
  root.scale.setScalar(0.92);
  const baseScale = 1.0;
  const timelines = [];

  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  }).to(root.scale, {
    x: baseScale,
    y: baseScale,
    z: baseScale,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  // ---------- interaction state ----------
  const restY = root.position.y;
  let hoverTl = null;
  let pressTl = null;

  function onHoverStart() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: restY + 0.15,
      duration: 0.35,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(accentMat, {
      opacity: 1.0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(hoverTl);
  }

  function onHoverEnd() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: restY,
      duration: 0.35,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(accentMat, {
      opacity: 0.0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(hoverTl);
  }

  function onClick() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: baseScale * 0.97,
      y: baseScale * 0.97,
      z: baseScale * 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    }).to(root.scale, {
      x: baseScale,
      y: baseScale,
      z: baseScale,
      duration: 0.2,
      ease: 'power2.out',
    });
    timelines.push(pressTl);
    ctx.emit('hub-journal.select', { nodeId: config.id ?? 'hub-journal-card-0-label' });
    ctx.emit('navigate', { to: 'hub-journal' });
  }

  root.userData.handlers = {
    pointerenter: onHoverStart,
    pointerover: onHoverStart,
    hoverStart: onHoverStart,
    pointerleave: onHoverEnd,
    pointerout: onHoverEnd,
    hoverEnd: onHoverEnd,
    pointerdown: onClick,
    click: onClick,
  };

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    timelines.length = 0;

    cardGeo.dispose();
    cardMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (accentIconMesh) {
      accentIconMesh.geometry.dispose();
      accentIconMesh.material.dispose();
    }
    if (accentIconTex) {
      accentIconTex.dispose();
    }

    if (text.userData?.cleanup) {
      text.userData.cleanup();
    }

    rimLight.dispose?.();
  };

  return root;
}
